const canvas=document.getElementById('floorCanvas'),empty=document.getElementById('emptyState');
const $=id=>document.getElementById(id);let items=[],selected=null,history=[],future=[],drag=null,underlayData=null;const PX=40,TATAMI=1.62;
const colors={リビング:'#f1e7d4',寝室:'#eee1dc',キッチン:'#e2ebdf',水まわり:'#dce9ee',外壁:'#414844',柱:'#4b514e'};
function uid(){return 'i'+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function snap(n){return $('snapToggle').checked?Math.round(n/20)*20:n}
function state(){return JSON.stringify(items)}
function checkpoint(){history.push(state());if(history.length>40)history.shift();future=[]}
function roomPoints(item){return item.points||[[0,0],[1,0],[1,1],[0,1]]}
function roomArea(item){const p=roomPoints(item);let sum=0;for(let i=0;i<p.length;i++){const a=p[i],b=p[(i+1)%p.length];sum+=a[0]*b[1]-b[0]*a[1]}return Math.abs(sum)/2*(item.w/PX)*(item.h/PX)}
function addItem(type,name,w,h,x,y,skip=false){if(!skip)checkpoint();const count=items.filter(i=>i.name.startsWith(name)).length+1;let item={id:uid(),type,name:type==='room'?`${name} ${count}`:name,x:x??80+items.length*18,y:y??80+items.length*16,w:w||(type==='furniture'?110:80),h:h||(type==='furniture'?55:type==='door'?55:18),rotation:0,color:colors[name]||'#e7e5dd'};if($('snapToggle').checked){item.x=snap(item.x);item.y=snap(item.y);item.w=Math.max(20,snap(item.w));item.h=Math.max(20,snap(item.h))}if(type==='room')item.points=[[0,0],[1,0],[1,1],[0,1]];items.push(item);setInspectorCollapsed(false);render();select(item.id);scheduleSave()}
function render(){canvas.querySelectorAll('.plan-item').forEach(e=>e.remove());items.forEach(item=>{const el=document.createElement('div');el.className=`plan-item ${item.type}${item.id===selected?' selected':''}`;el.dataset.id=item.id;Object.assign(el.style,{left:item.x+'px',top:item.y+'px',width:item.w+'px',height:item.h+'px',background:item.type==='door'?'transparent':item.color,transform:`rotate(${item.rotation}deg)`});if(item.type==='room')el.style.clipPath=`polygon(${roomPoints(item).map(p=>`${p[0]*100}% ${p[1]*100}%`).join(',')})`;const area=item.type==='room'?roomArea(item):0;el.innerHTML=`<div class="item-label"><strong>${item.name}</strong>${item.type==='room'?`<small>${area.toFixed(1)} m² / ${(area/TATAMI).toFixed(1)} 畳</small>`:''}</div><span class="resize-handle"></span>${item.type==='room'&&item.id===selected?roomPoints(item).map((p,n)=>`<button class="vertex-handle" data-vertex="${n}" aria-label="頂点 ${n+1}" style="left:${p[0]*100}%;top:${p[1]*100}%"></button>`).join(''):''}`;el.addEventListener('pointerdown',startDrag);canvas.appendChild(el)});empty.style.display=items.length?'none':'flex';updateSummary();updateInspector()}
function startDrag(e){e.preventDefault();const id=e.currentTarget.dataset.id;select(id);const item=items.find(i=>i.id===id);checkpoint();const vertex=e.target.dataset.vertex;drag={id,startX:e.clientX,startY:e.clientY,x:item.x,y:item.y,w:item.w,h:item.h,resize:e.target.classList.contains('resize-handle'),vertex:vertex===undefined?null:+vertex,points:roomPoints(item).map(p=>[...p])};window.addEventListener('pointermove',onMove);window.addEventListener('pointerup',endDrag,{once:true})}
function onMove(e){if(!drag)return;const item=items.find(i=>i.id===drag.id),z=Number($('zoom').value)/100,dx=(e.clientX-drag.startX)/z,dy=(e.clientY-drag.startY)/z;if(drag.vertex!==null){item.points=drag.points.map(p=>[...p]);item.points[drag.vertex]=[Math.max(0,Math.min(1,drag.points[drag.vertex][0]+dx/item.w)),Math.max(0,Math.min(1,drag.points[drag.vertex][1]+dy/item.h))]}else if(drag.resize){item.w=Math.max(30,snap(drag.w+dx));item.h=Math.max(item.type==='wall'?6:20,snap(drag.h+dy))}else{item.x=Math.max(0,Math.min(canvas.clientWidth-item.w,snap(drag.x+dx)));item.y=Math.max(0,Math.min(canvas.clientHeight-item.h,snap(drag.y+dy)))}render()}
function endDrag(){window.removeEventListener('pointermove',onMove);drag=null;scheduleSave()}
function select(id){selected=id;render()}
function setInspectorCollapsed(collapsed){$('inspectorPanel').classList.toggle('collapsed',collapsed);$('minimizeInspectorBtn').textContent=collapsed?'＋':'−';$('inspectorHeader').setAttribute('aria-label',collapsed?'プロパティを開く':'プロパティ')}
$('minimizeInspectorBtn').onclick=e=>{e.stopPropagation();setInspectorCollapsed(!$('inspectorPanel').classList.contains('collapsed'))};$('inspectorHeader').onclick=()=>{if($('inspectorPanel').classList.contains('collapsed'))setInspectorCollapsed(false)};$('inspectorHeader').onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&$('inspectorPanel').classList.contains('collapsed')){e.preventDefault();setInspectorCollapsed(false)}};
function updateInspector(){const item=items.find(i=>i.id===selected);$('noSelection').classList.toggle('hidden',!!item);$('propertyForm').classList.toggle('hidden',!item);if(!item)return;$('propName').value=item.name;$('propW').value=(item.w/PX).toFixed(1);$('propH').value=(item.h/PX).toFixed(1);$('propRotation').value=item.rotation;$('rotationLabel').textContent=item.rotation+'°';$('addVertexBtn').classList.toggle('hidden',item.type!=='room');$('thicknessField').classList.toggle('hidden',item.type!=='wall');$('propThickness').value=Math.round(item.h/PX*100);document.querySelectorAll('#swatches button').forEach(b=>b.classList.toggle('active',b.dataset.color===item.color))}
function updateSummary(){const rooms=items.filter(i=>i.type==='room'),area=rooms.reduce((a,i)=>a+roomArea(i),0),tatami=area/TATAMI;$('roomCount').textContent=rooms.length;$('totalArea').textContent=`${area.toFixed(1)} m² / ${tatami.toFixed(1)} 畳`;$('statusSummary').textContent=`${rooms.length} 部屋 ・ ${area.toFixed(1)} m² / ${tatami.toFixed(1)} 畳`}
function mutate(fn){const item=items.find(i=>i.id===selected);if(!item)return;checkpoint();fn(item);render();scheduleSave()}
document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addItem(b.dataset.add,b.dataset.name,+b.dataset.w||0,+b.dataset.h||0));
$('propName').onchange=e=>mutate(i=>i.name=e.target.value||'名称未設定');$('propW').onchange=e=>mutate(i=>i.w=Math.max(20,+e.target.value*PX));$('propH').onchange=e=>mutate(i=>i.h=Math.max(6,+e.target.value*PX));$('propRotation').oninput=e=>mutate(i=>i.rotation=+e.target.value);$('propThickness').onchange=e=>mutate(i=>i.h=Math.max(2,+e.target.value/100*PX));document.querySelectorAll('#swatches button').forEach(b=>b.onclick=()=>mutate(i=>i.color=b.dataset.color));
$('addVertexBtn').onclick=()=>mutate(i=>{const p=roomPoints(i),edge=p.map((a,n)=>{const b=p[(n+1)%p.length];return{n,d:(a[0]-b[0])**2+(a[1]-b[1])**2}}).sort((a,b)=>b.d-a.d)[0],n=edge.n,a=p[n],b=p[(n+1)%p.length];i.points=[...p.slice(0,n+1),[(a[0]+b[0])/2,(a[1]+b[1])/2],...p.slice(n+1)]});
$('deleteBtn').onclick=()=>{if(!selected)return;checkpoint();items=items.filter(i=>i.id!==selected);selected=null;render();scheduleSave()};$('duplicateBtn').onclick=()=>{const i=items.find(x=>x.id===selected);if(i){checkpoint();const copy=JSON.parse(JSON.stringify(i));copy.id=uid();copy.x+=20;copy.y+=20;items.push(copy);selected=copy.id;setInspectorCollapsed(false);render();scheduleSave()}};
$('undoBtn').onclick=()=>{if(!history.length)return;future.push(state());items=JSON.parse(history.pop());selected=null;render();scheduleSave()};$('redoBtn').onclick=()=>{if(!future.length)return;history.push(state());items=JSON.parse(future.pop());selected=null;render();scheduleSave()};
function setZoom(value){const z=Math.max(25,Math.min(200,+value));$('zoom').value=z;canvas.style.zoom=z/100;$('zoomLabel').textContent=z+'%';$('zoomDockLabel').textContent=z+'%'}$('zoom').oninput=e=>setZoom(e.target.value);$('zoomOutBtn').onclick=$('zoomOutDockBtn').onclick=()=>setZoom(+$('zoom').value-10);$('zoomInBtn').onclick=$('zoomInDockBtn').onclick=()=>setZoom(+$('zoom').value+10);
$('resetPlanBtn').onclick=()=>{if(!items.length){toast('リセットする配置はありません');return}if(!confirm('配置した部屋・壁・家具をすべて削除しますか？\n「元に戻す」で復元できます。'))return;checkpoint();items=[];selected=null;render();scheduleSave();toast('配置をすべてリセットしました')};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-mode]').forEach(x=>x.classList.remove('active'));b.classList.add('active')});
let saveTimer;function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(save,500)}function save(){localStorage.setItem('madori-data',JSON.stringify({items,name:$('projectName').value}));toast('保存しました')}$('saveBtn').onclick=save;$('projectName').onchange=scheduleSave;
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1700)}
$('exportBtn').onclick=()=>{const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="620"><rect width="100%" height="100%" fill="#fdfcf9"/>${items.map(i=>{const shape=i.type==='room'?`<polygon points="${roomPoints(i).map(p=>`${p[0]*i.w},${p[1]*i.h}`).join(' ')}" fill="${i.color}" stroke="#56615b" stroke-width="2"/>`:`<rect width="${i.w}" height="${i.h}" fill="${i.type==='door'?'none':i.color}" stroke="#56615b" stroke-width="2"/>`;const area=i.type==='room'?roomArea(i):0;return `<g transform="translate(${i.x} ${i.y}) rotate(${i.rotation} ${i.w/2} ${i.h/2})">${shape}<text x="${i.w/2}" y="${i.h/2}" text-anchor="middle" dominant-baseline="middle" font-family="sans-serif" font-size="13" fill="#25312d">${i.name.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}${i.type==='room'?` ${area.toFixed(1)}㎡/${(area/TATAMI).toFixed(1)}畳`:''}</text></g>`}).join('')}</svg>`;const image=new Image(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));image.onload=()=>{const c=document.createElement('canvas');c.width=900;c.height=620;c.getContext('2d').drawImage(image,0,0);const a=document.createElement('a');a.download=($('projectName').value||'間取り')+'.png';a.href=c.toDataURL('image/png');a.click();URL.revokeObjectURL(url);toast('PNGを書き出しました')};image.src=url};

// ChatGPTなどで生成した間取り画像を、編集用の下絵として読み込む。
$('importBtn').onclick=$('importSidebarBtn').onclick=()=>$('planImageInput').click();
$('planImageInput').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.size>8*1024*1024){toast('8MB以下の画像を選んでください');return}const reader=new FileReader();reader.onload=()=>{underlayData=reader.result;$('planUnderlay').src=underlayData;$('planUnderlay').classList.remove('hidden');$('imageControls').classList.remove('hidden');try{localStorage.setItem('madori-underlay',underlayData)}catch{toast('画像は表示中のみ保持されます')}toast('間取り画像を下絵に追加しました')};reader.readAsDataURL(file);e.target.value=''};
