$('removeImageBtn').onclick=()=>{underlayData=null;$('planUnderlay').src='';$('planUnderlay').classList.add('hidden');$('imageControls').classList.add('hidden');localStorage.removeItem('madori-underlay');toast('下絵を削除しました')};

// 希望条件から、編集可能な初期レイアウトをローカルで組み立てる。
function generatedItem(type,name,x,y,w,h,color,rotation=0){const item={id:uid(),type,name,x,y,w,h,rotation,color};if(type==='room')item.points=[[0,0],[1,0],[1,1],[0,1]];return item}
function generatePlanFromText(text,keep){checkpoint();if(!keep)items=[];const start=items.length,ldk=Math.max(1,Math.min(4,+((text.match(/([1-4])\s*LDK/i)||[])[1]||1))),range=text.match(/(\d+)\s*[〜~～-]\s*(\d+)\s*(?:㎡|平米)/),single=text.match(/(\d+)\s*(?:㎡|平米)/),target=range?(+range[1]+ +range[2])/2:single?+single[1]:55,base=88+(ldk-1)*18,scale=Math.max(.62,Math.min(1.18,Math.sqrt(target/base))),S=n=>Math.max(20,Math.round(n*scale/20)*20),ox=0,oy=0;
  const rooms=[generatedItem('room','LDK',ox,oy,S(320),S(220),'#f1e7d4'),generatedItem('room','寝室 1',ox+S(320),oy,S(240),S(210),'#eee1dc'),generatedItem('room','洗面・脱衣',ox,oy+S(220),S(150),S(120),'#dce9ee'),generatedItem('room','浴室',ox+S(150),oy+S(220),S(110),S(120),'#d6e5eb'),generatedItem('room','玄関',ox+S(260),oy+S(220),S(120),S(100),'#e8e4df')];
  for(let n=2;n<=ldk;n++)rooms.push(generatedItem('room',`寝室 ${n}`,ox+S(320),oy+S(210+(n-2)*130),S(240),S(120),'#e8e4ef'));
  items.push(...rooms);const maxX=Math.max(...rooms.map(r=>r.x+r.w)),maxY=Math.max(...rooms.map(r=>r.y+r.h)),t=20;items.push(generatedItem('wall','外壁',ox-t,oy-t,maxX-ox+t*2,t,'#414844'),generatedItem('wall','外壁',ox-t,maxY,maxX-ox+t*2,t,'#414844'),generatedItem('wall','外壁',ox-t,oy,t,maxY-oy,'#414844'),generatedItem('wall','外壁',maxX,oy,t,maxY-oy,'#414844'));
  items.push(generatedItem('furniture',/アイランド/.test(text)?'アイランドキッチン':'キッチン',ox+S(80),oy+S(40),S(150),S(60),'#d7ddd2'),generatedItem('furniture','ソファ',ox+S(80),oy+S(140),S(110),S(60),'#d9d2c8'),generatedItem('furniture','ベッド',ox+S(380),oy+S(60),S(120),S(160),'#ded8d3'),generatedItem('door','玄関ドア',ox+S(280),maxY-40,S(60),60,'#e7e5dd'));
  const group=items.slice(start),minX=Math.min(...group.map(i=>i.x)),minY=Math.min(...group.map(i=>i.y)),groupMaxX=Math.max(...group.map(i=>i.x+i.w)),groupMaxY=Math.max(...group.map(i=>i.y+i.h)),dx=snap((canvas.clientWidth-(groupMaxX-minX))/2-minX),dy=snap((canvas.clientHeight-(groupMaxY-minY))/2-minY);group.forEach(i=>{i.x=snap(i.x+dx);i.y=snap(i.y+dy)});
  selected=rooms[0].id;setInspectorCollapsed(false);render();scheduleSave();$('autoPlanModal').classList.add('hidden');toast(`${ldk}LDK・約${Math.round(target)}㎡のたたき台を作成しました`)}
$('autoPlanBtn').onclick=()=>$('autoPlanModal').classList.remove('hidden');$('cancelAutoPlanBtn').onclick=()=>$('autoPlanModal').classList.add('hidden');$('generatePlanBtn').onclick=()=>generatePlanFromText($('autoPlanPrompt').value,$('keepExistingPlan').checked);$('autoPlanModal').onclick=e=>{if(e.target===$('autoPlanModal'))$('autoPlanModal').classList.add('hidden')};

// 配置済みの部屋輪郭・外壁・柱を線分に変換し、軽量な一人称ビューを描画する。
const walk={x:450,y:310,a:0,keys:new Set(),raf:0};
function rotatePoint(x,y,cx,cy,a){const r=a*Math.PI/180,dx=x-cx,dy=y-cy;return[cx+dx*Math.cos(r)-dy*Math.sin(r),cy+dx*Math.sin(r)+dy*Math.cos(r)]}
function planSegments(){const seg=[];items.forEach(i=>{if(i.type==='room'){const p=roomPoints(i).map(v=>rotatePoint(i.x+v[0]*i.w,i.y+v[1]*i.h,i.x+i.w/2,i.y+i.h/2,i.rotation));p.forEach((a,n)=>seg.push({a,b:p[(n+1)%p.length],color:i.color}))}else if(i.type==='wall'||i.type==='pillar'){const p=[[i.x,i.y],[i.x+i.w,i.y],[i.x+i.w,i.y+i.h],[i.x,i.y+i.h]].map(v=>rotatePoint(v[0],v[1],i.x+i.w/2,i.y+i.h/2,i.rotation));p.forEach((a,n)=>seg.push({a,b:p[(n+1)%p.length],color:i.color}))}});return seg}
function rayHit(px,py,angle,segments){const dx=Math.cos(angle),dy=Math.sin(angle);let best=null;segments.forEach(s=>{const sx=s.b[0]-s.a[0],sy=s.b[1]-s.a[1],den=dx*sy-dy*sx;if(Math.abs(den)<.0001)return;const qx=s.a[0]-px,qy=s.a[1]-py,t=(qx*sy-qy*sx)/den,u=(qx*dy-qy*dx)/den;if(t>0&&u>=0&&u<=1&&(!best||t<best.d))best={d:t,color:s.color}});return best}
function hexRgb(hex){const h=(hex||'#747b72').replace('#','');return[h.length===3?parseInt(h[0]+h[0],16):parseInt(h.slice(0,2),16),h.length===3?parseInt(h[1]+h[1],16):parseInt(h.slice(2,4),16),h.length===3?parseInt(h[2]+h[2],16):parseInt(h.slice(4,6),16)]}
function drawWalk(){const c=$('walkCanvas'),ctx=c.getContext('2d'),w=c.width,h=c.height,segments=planSegments();ctx.fillStyle='#cfd8d3';ctx.fillRect(0,0,w,h/2);ctx.fillStyle='#8b8277';ctx.fillRect(0,h/2,w,h/2);const fov=Math.PI/3;for(let x=0;x<w;x+=3){const ra=walk.a-fov/2+fov*x/w,hit=rayHit(walk.x,walk.y,ra,segments);if(!hit)continue;const d=Math.max(1,hit.d*Math.cos(ra-walk.a)),height=Math.min(h*1.8,15000/d),[r,g,b]=hexRgb(hit.color),shade=Math.max(.28,1-d/900);ctx.fillStyle=`rgb(${r*shade},${g*shade},${b*shade})`;ctx.fillRect(x,(h-height)/2,4,height)}ctx.fillStyle='#ffffffaa';ctx.font='13px sans-serif';ctx.fillText(`位置 ${Math.round(walk.x)}, ${Math.round(walk.y)}`,18,h-18);updateWalk();walk.raf=requestAnimationFrame(drawWalk)}
function updateWalk(){const speed=walk.keys.has('Shift')?4:2.2;if(walk.keys.has('ArrowLeft')||walk.keys.has('a'))walk.a-=.035;if(walk.keys.has('ArrowRight')||walk.keys.has('d'))walk.a+=.035;let move=0;if(walk.keys.has('ArrowUp')||walk.keys.has('w'))move=speed;if(walk.keys.has('ArrowDown')||walk.keys.has('s'))move=-speed;walk.x=Math.max(0,Math.min(900,walk.x+Math.cos(walk.a)*move));walk.y=Math.max(0,Math.min(620,walk.y+Math.sin(walk.a)*move))}
$('view3dBtn').onclick=()=>{if(!items.some(i=>i.type==='room'||i.type==='wall')){toast('部屋または外壁を追加してください');return}const room=items.find(i=>i.type==='room');if(room){walk.x=room.x+room.w/2;walk.y=room.y+room.h/2}walk.a=0;$('walkModal').classList.remove('hidden');cancelAnimationFrame(walk.raf);drawWalk()};
function closeWalk(){cancelAnimationFrame(walk.raf);walk.keys.clear();$('walkModal').classList.add('hidden')}$('closeWalkBtn').onclick=closeWalk;
window.addEventListener('keydown',e=>{if(!$('walkModal').classList.contains('hidden')){walk.keys.add(e.key);if(e.key==='Escape')closeWalk();e.preventDefault()}});window.addEventListener('keyup',e=>walk.keys.delete(e.key));
window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='z'){$('undoBtn').click();e.preventDefault()}if((e.key==='Delete'||e.key==='Backspace')&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName))$('deleteBtn').click()});canvas.onclick=e=>{if(e.target===canvas){selected=null;render()}};
try{const d=JSON.parse(localStorage.getItem('madori-data'));if(d){items=d.items||[];$('projectName').value=d.name||'わが家のプラン A'}underlayData=localStorage.getItem('madori-underlay');if(underlayData){$('planUnderlay').src=underlayData;$('planUnderlay').classList.remove('hidden');$('imageControls').classList.remove('hidden')}}catch{}render();
